function validate(b){if(b?.format!=='MinuitProgression'||b.version!==1||!b.saves||typeof b.saves!=='object')throw Error('Ce fichier n’est pas une sauvegarde La Nuit aux Trousses compatible.');function walk(v,depth=0){if(depth>20)throw Error('Sauvegarde trop complexe.');if(typeof v==='number'&&(!Number.isFinite(v)||Math.abs(v)>1e15))throw Error('Valeur numérique invalide.');if(typeof v==='string'&&v.length>5000)throw Error('Texte trop long.');if(v&&typeof v==='object'){if(Object.keys(v).length>10000)throw Error('Sauvegarde trop volumineuse.');for(const [k,x]of Object.entries(v)){if(['__proto__','prototype','constructor'].includes(k))throw Error('Champ interdit.');walk(x,depth+1)}}}walk(b);for(const k of Object.keys(b.saves))if(!exportKeys.includes(k))throw Error('Donnée inconnue dans la sauvegarde.');const p=b.saves[KEY],l=b.saves['minuit-local-league-v1'],cp=b.saves['minuit-checkpoint'];if(!p||p.version!==1||!Number.isFinite(p.xp)||p.xp<0||!p.days||!p.seen||!p.selected||!Array.isArray(p.achievements)||!Array.isArray(p.activeDates)||!Array.isArray(p.recent))throw Error('Progression invalide.');for(const [k,v] of Object.entries(p.selected))if(!items.some(i=>i.kind===k&&i.id===v))throw Error('Cosmétique inconnu.');if(!l?.days||!l?.runs)throw Error('Cumul local invalide.');for(const [day,d] of Object.entries(l.days)){if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||!['best','bonus','rankedUsed','dailyUsed'].every(k=>Number.isFinite(d[k])&&d[k]>=0)||!d.stats||!Array.isArray(d.claimed))throw Error('Journée de défi invalide.')}for(const d of Object.values(p.days))if(!d.stats||!Array.isArray(d.claimed))throw Error('Carnet invalide.');for(const s of Object.values(p.seen))if(!s.stats||!Number.isFinite(s.paid))throw Error('Historique invalide.');if(cp&&(![4,5,6,7,8].includes(cp.version)||!Number.isInteger(cp.stage)||cp.stage<0||cp.stage>4||!Number.isInteger(cp.wave)||cp.wave<1||cp.wave>5||!cp.player||!cp.upgrades||!Array.isArray(cp.schedule)))throw Error('Point de reprise invalide.');const statMap=o=>o&&typeof o==='object'&&!Array.isArray(o)&&Object.values(o).every(n=>Number.isFinite(n)&&n>=0);if(!statMap(p.lifetime)||!Array.isArray(p.weeks)||p.weeks.some(w=>typeof w!=='string')||p.activeDates.some(d=>typeof d!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d))||p.achievements.some(id=>!achievementRules[id])||typeof p.tutorialDone!=='boolean'||p.trainingDone!==undefined&&typeof p.trainingDone!=='boolean'||p.dodgeGuideDone!==undefined&&typeof p.dodgeGuideDone!=='boolean'||!Number.isFinite(p.streak)||p.streak<0)throw Error('Profil invalide.');for(const d of Object.values(p.days))if(!statMap(d.stats)||d.claimed.some(id=>!contracts.some(c=>c.id===id)))throw Error('Contrats invalides.');for(const d of Object.values(l.days))if(!statMap(d.stats)||d.rankedUsed>3||d.dailyUsed>1)throw Error('Défis invalides.');for(const d of Object.values(p.seen))if(!statMap(d.stats)||typeof d.done!=='boolean')throw Error('Vol invalide.');for(const r of p.recent)if(!r||typeof r.id!=='string'||typeof r.day!=='string'||typeof r.world!=='string'||typeof r.cause!=='string'||!statMap(r.stats)||!Number.isFinite(r.score))throw Error('Journal invalide.');for(const r of p.recent)if(r.comment!==undefined&&(typeof r.comment!=='string'||r.comment.length>1000))throw Error('Commentaire invalide.');for(const r of Object.values(l.runs))if(!r||typeof r.id!=='string'||!['ranked','daily'].includes(r.mode)||typeof r.day!=='string'||!statMap(r.stats)||!Number.isFinite(r.score)||typeof r.finished!=='boolean'||!Array.isArray(r.credited))throw Error('Essai local invalide.');if(cp?.journey&&(!statMap(cp.journey.stats)||typeof cp.journey.id!=='string'||!['free','ranked','daily'].includes(cp.journey.mode)))throw Error('Progression du vol invalide.');const settings=b.saves['minuit-settings'];if(settings&&(!settings.keys||!['easy','normal','hard'].includes(settings.difficulty)||settings.touchLayout!==undefined&&!['standard','left','right'].includes(settings.touchLayout)))throw Error('Réglages invalides.');const scores=b.saves['minuit-v2-scores'];if(scores&&(!Array.isArray(scores)||scores.some(r=>!r||!Number.isFinite(r.score)||r.score<0||typeof r.name!=='string'||!['easy','normal','hard','daily'].includes(r.category))))throw Error('Records invalides.');const high=b.saves['minuit-highscores'];if(high&&!statMap(high))throw Error('HI-SCORE invalide.');if(settings&&(typeof settings.name!=='string'||Object.values(settings.keys).some(k=>typeof k!=='string')))throw Error('Touches invalides.');if(cp&&(!Number.isFinite(cp.score)||!Number.isFinite(cp.lives)||!Number.isFinite(cp.gameTime)||!Number.isFinite(cp.diff)||!Number.isFinite(cp.player.x)||!Number.isFinite(cp.player.y)))throw Error('Point de reprise corrompu.');if(cp?.sweets&&(!Array.isArray(cp.sweets)||cp.sweets.length>20||cp.sweets.some(d=>!d||d.kind!=='sweet'||!['xp','points','shield'].includes(d.sweetType)||!Number.isFinite(d.x)||!Number.isFinite(d.y)||!Number.isFinite(d.xp)||d.xp<0||d.xp>1000||!Number.isFinite(d.points)||d.points<0||d.points>50000)))throw Error('Bonbons de sauvegarde invalides.');window.Arsenal?.validateSave?.(b);window.Adventure?.validateSave?.(b);window.Nemesis?.validateSave?.(b);return b}
async function importSave(file,status){
 try{
  if(!file)return false;if(file.size>2*1024*1024)throw Error('Fichier trop volumineux (2 Mo maximum).');
  const b=validate(JSON.parse(await file.text()));if(!confirm('Remplacer ta progression locale par cette sauvegarde ? Une copie de secours sera conservée dans ce navigateur.'))return false;
  const previous={};for(const k of exportKeys)previous[k]=localStorage.getItem(k);localStorage.setItem('minuit-import-rollback',JSON.stringify(previous));window.MinuitImporting=true;
  try{for(const k of exportKeys){if(b.saves[k]==null)localStorage.removeItem(k);else localStorage.setItem(k,JSON.stringify(b.saves[k]))}}catch(e){for(const k of exportKeys){if(previous[k]==null)localStorage.removeItem(k);else localStorage.setItem(k,previous[k])}window.MinuitImporting=false;throw Error('Stockage insuffisant. Import annulé.')}
  location.reload();return true;
 }catch(e){status.textContent=e instanceof SyntaxError?'Fichier JSON illisible. Aucun changement effectué.':e.message;return false}
}
function cloudControl(){return '<div id="supabaseMount"></div>'}
function localSaveControls(){return '<div class="journey-save-controls"><button class="secondary" id="exportJourney">Exporter ma progression</button><label class="secondary journey-import">Importer une sauvegarde<input id="importJourney" type="file" accept=".json,application/json"></label></div><div class="journey-small" id="saveMessage">Fichier JSON : progression, cosmétiques, records, réglages et point de reprise. La session du compte en ligne n’est jamais incluse.</div>'}
function saveControls(){return cloudControl()+localSaveControls()}
function bindSave(){const ex=$('exportJourney'),im=$('importJourney');if(ex)ex.onclick=exportSave;if(im)im.onchange=()=>importSave(im.files[0],$('saveMessage'));window.MinuitCloud?.renderPanel?.($('supabaseMount'))}
function selectArchiveTab(tab){
 const local=tab==='local';
 $('accountCloudPanel').classList.toggle('hidden',local);$('accountLocalPanel').classList.toggle('hidden',!local);
 for(const [id,active] of [['archiveAccountTab',!local],['archiveLocalTab',local]]){const button=$(id);button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active))}
 $('accountPageTitle').textContent=local?'Vols & sauvegarde':'Compte & team';
 $('accountPageIntro').textContent=local?'Exporte une copie de ta progression, puis retrouve tes derniers vols dans un journal séparé.':'Ton accès en ligne et ta team, sans mélanger tes fichiers locaux et ton historique.';
}
function archives(tab){
 if(state==='play')pauseScreen();state='journey-archives';
 const history=j.recent.slice(0,8).map(r=>`<div><span>${safeText(r.day)} · ${safeText(r.world)} · V${r.wave}<br><small>${safeText(r.cause)} · ${r.stats.hits||0} impacts · ${r.feedback?({hard:'trop difficile',fair:'bien dosé',easy:'trop facile'})[r.feedback]:'avis non renseigné'}</small></span><b>${fmt(r.score)} pts</b></div>`).join('')||'<p>Ton prochain vol ouvrira ce journal.</p>';
 overlay(`<section class="account-page"><header class="account-header"><div class="eyebrow">TON ESPACE DE JEU</div><h2 class="local-title" id="accountPageTitle">Compte & team</h2><p id="accountPageIntro"></p></header><div class="account-tabs" role="tablist" aria-label="Compte, team et sauvegardes"><button type="button" id="archiveAccountTab" role="tab" aria-controls="accountCloudPanel" aria-selected="true">☁ Compte & team</button><button type="button" id="archiveLocalTab" role="tab" aria-controls="accountLocalPanel" aria-selected="false">↻ Vols & sauvegarde</button></div><section class="account-panel" id="accountCloudPanel" role="tabpanel" aria-labelledby="archiveAccountTab">${cloudControl()}</section><section class="account-panel hidden" id="accountLocalPanel" role="tabpanel" aria-labelledby="archiveLocalTab"><section class="local-backup-card"><h3>SAUVEGARDE LOCALE</h3><p>Exporte avant de changer d’appareil. L’import remplace la progression actuelle et conserve une possibilité d’annulation.</p>${localSaveControls()}<button class="secondary rollback-import" id="rollbackImport">Annuler le dernier import</button></section><section class="journey-history"><h3>DERNIERS VOLS · DONNÉES LOCALES</h3>${history}</section><p class="journey-small">Les avis restent dans ton journal local. Avec le compte en ligne configuré, tu peux transmettre une copie privée pour l’équilibrage ; ils ne sont jamais affichés sur un mur public.</p></section><footer class="account-footer"><button class="primary" id="archivesBack">Retour à l’accueil →</button></footer></section>`);
 bindSave();$('archiveAccountTab').onclick=()=>selectArchiveTab('account');$('archiveLocalTab').onclick=()=>selectArchiveTab('local');selectArchiveTab(tab==='local'?'local':'account');
 $('archivesBack').onclick=LocalLeague.menu;
 $('rollbackImport').onclick=()=>{try{const v=JSON.parse(localStorage.getItem('minuit-import-rollback')||'null');if(!v)throw Error('Aucun import à annuler.');if(!confirm('Restaurer la progression antérieure au dernier import ?'))return;window.MinuitImporting=true;for(const k of exportKeys){if(v[k]==null)localStorage.removeItem(k);else localStorage.setItem(k,v[k])}localStorage.removeItem('minuit-import-rollback');location.reload()}catch(e){$('saveMessage').textContent=e.message}};
}
